room {
  -"библиотека";
  nam = "библиотека";
  title = "Библиотека Правления";
  dsc = function(s)
    fn_say("Высокий зал с винтовыми чугунными лестницами. По рельсам вдоль полок скользят стремянки с захватами. На пюпитре — прикованный цепью фолиант чертежей. Пахнет пылью и кожей переплётов. Позади — дверь в галерею.")
    if not dnevnik then
      fn_say("Между листами со схемами пневмоприводов зажат черновик записки с пятнами сажи.")
    end
  end;
  before_Exam = function(s, w, wh)
    if w == _'дневник' and not dnevnik then
      fn_say("«Они именуют себя Избавителями от страданий. Их логика проста: живой человек голодает, мёрзнет и мыслит. Заводной автомат, оживлённый человеческим сердцем, сыт и покорен. Сюзанну увели на нижний горизонт...»")
      dnevnik = true
    elseif w == _'полки' then
      fn_say("Атласы по часовым механизмам, анатомия гидравлических кукол, финансовые гроссбухи. Среди них — старые морские карты: Зурбаган, Лисс, Гель-Гью. Схемы подключения живых вен к золотниковым коробкам помечены «Одобрено к производству».")
    else
      return false
    end
  end;
  obj = {
    obj {
      -"дневник,черновик|записка";
      nam = "дневник";
    }:attr 'scenery,scenery';

    obj {
      -"полки,атласы|карты|стеллажи";
      nam = "полки";
    }:attr 'scenery,scenery';

    obj {
      -"коридор|галерея";
      nam = "путь_библиотека_коридор";
      before_Walk = function(s, w, wh)
        move(me(), _'коридор')
      end;
      before_Enter = function(s, w, wh)
        move(me(), _'коридор')
      end;
    }:attr 'scenery,scenery';
  };
}

room {
  -"архив";
  nam = "архив";
  title = "Секретный архив";
  dsc = function(s)
    fn_say("Каземат без окон, освещённый дуговой лампой. Вдоль стен — стальные шкафы. За столом — женщина с землистым лицом и короткими волосами. На стене — огромное полотно в позолоченной раме. Позади — дверь в галерею.")
    if arch_open then
      fn_say("Полотно сдвинуто по рельсам. В нише — круглая дверца сейфа, как корабельный люк.")
    end
  end;
  before_Exam = function(s, w, wh)
    if w == _'картина' then
      fn_say("Залитый солнцем Зурбаган. Белые террасы, лазурная бухта, клипера на волне, акации. От полотна веет солью и теплом нагретого камня.")
    elseif w == _'рама' then
      if not have(_'осколок') and not arch_open then
        fn_say("Рама сплошная, вмурованная в кладку.")
      elseif have(_'осколок') and not arch_open then
        fn_say("Сквозь скол видна зубчатая передача за позолотой. Полотно — на скрытых рельсах сейфа.")
      else
        fn_say("Полотно уже отъехало, открывая нишу с сейфом.")
      end
    else
      return false
    end
  end;
  before_Turn = function(s, w, wh)
    if w == _'код_архив' and not arch_open then
      if code_known then
        fn_say("Вы провернули лимб: 4-12-709. Свист воздуха, и картина отъехала в сторону.")
        arch_open = true
      else
        fn_say("Вы вертите лимб наугад. Механизм молчит — нужно знать комбинацию.")
      end
    else
      return false
    end
  end;
  before_Talk = function(s, w, wh)
    if w == _'женщина' and not poet_saved and not poet_lost then
      fn_say('Она пишет карандашом на обороте ведомости. "Я записываю живой мир, пока город не переплавили в чугун. Пока звучит строка — автоматоны не победили."')
    else
      return false
    end
  end;
  before_Yes = function(s, w, wh)
    if not poet_saved and not poet_lost then
      fn_say('"Пишите. Ваше слово сильнее всех шестерёнок". Женщина поднимает глаза: "Возьмите песнь о Зурбагане и карандаш. Она — для тех, чьё сердце не согласно стать механизмом."')
      poet_saved = true
      enable(_'поэма')
      take(_'поэма')
    else
      return false
    end
  end;
  before_No = function(s, w, wh)
    if not poet_saved and not poet_lost then
      fn_say('"Бросьте рифмы. В этом мире выживают сталью и пайками". Женщина гасит лампу и уходит во тьму.')
      poet_lost = true
    else
      return false
    end
  end;
  before_Enter = function(s, w, wh)
    if w == _'сейф_архив' then
      if arch_open and have(_'поэма') then
        move(me(), _'зурбаган')
      elseif arch_open and not have(_'поэма') then
        fn_say("Вы шагнули в люк, но упёрлись в глухую заслонку. Без живой мечты этот ход мёртв.")
      else
        fn_say("Сейф ещё закрыт.")
      end
    else
      return false
    end
  end;
  obj = {
    obj {
      -"картина|полотно|зурбаган";
      nam = "картина";
    }:attr 'scenery,scenery';

    obj {
      -"рама,позолота";
      nam = "рама";
    }:attr 'scenery,scenery';

    obj {
      -"женщина,поэтесса";
      nam = "женщина";
    }:attr 'animate';

    obj {
      -"стихи|песнь,строка";
      nam = "стихи";
    }:attr 'scenery,scenery';

    obj {
      -"смирение|покой,порядок";
      nam = "смирение";
    }:attr 'scenery,scenery';

    obj {
      -"сейф,люк|дверца";
      nam = "сейф_архив";
    }:attr 'scenery,scenery,enterable';

    obj {
      -"код|комбинация|лимб,412709,709|цифры";
      nam = "код_архив";
    }:attr 'scenery,scenery';

    obj {
      -"коридор|галерея";
      nam = "путь_архив_коридор";
      before_Walk = function(s, w, wh)
        move(me(), _'коридор')
      end;
      before_Enter = function(s, w, wh)
        move(me(), _'коридор')
      end;
    }:attr 'scenery,scenery';
  };
}

room {
  -"кабинет";
  nam = "кабинет";
  title = "Кабинет Председателя";
  dsc = function(s)
    fn_say("Овальный зал в стиле ампир. В камине горят дрова. Вдоль стен — двадцать портретов хозяина: на каждом следующем он выше и величественнее. За пультом из красного дерева сидит господин в цилиндре и визитке. Под его ладонью — тяжёлая серебряная печать Правления. Рядом — модель парусника под стеклом, тонкая, как паутина. Позади — дверь в галерею.")
    if not bird_freed then
      fn_say("На каминной полке в золочёной клетке — заводной соловей. Рубиновые глаза.")
    end
    if bird_freed then
      fn_say("Клетка пуста, дверца распахнута.")
    end
    if boss_banished then
      fn_say("Камин чадит. В кресле — цилиндр, опавшая визитка и горсть пепла.")
    end
    if boss_banished and not have(_'печать') then
      fn_say("На пульте — тяжёлая серебряная печать Правления.")
    end
  end;
  before_Exam = function(s, w, wh)
    if w == _'клетка' then
      if not bird_freed then
        fn_say("В клетке — искусная латунная птица. При шаге её пружина сухо щёлкает, имитируя щебет.")
      else
        fn_say("Дверца распахнута настежь. Клетка пуста.")
      end
    elseif w == _'парусник' then
      if not boss_banished then
        fn_say("Тонкая работа. Паруса — из пергамента, рангоут — из меди. На борту — имя: «Зурбаган». Хозяин держит его под стеклом, как держат сердце.")
      else
        fn_say("Модель парусника «Зурбаган» цела. Стекло треснуло от жара камина, но корабль уцелел.")
      end
    else
      return false
    end
  end;
  before_Open = function(s, w, wh)
    if w == _'клетка' then
      if boss_banished and not bird_freed then
        fn_say("Вы откинули крючок. Соловей встрепенулся, издал чистую трель — словно свобода вдохнула душу в металл — и спорхнул на карниз открытой форточки, растворившись серебряным отблеском в метели.")
        bird_freed = true
      elseif bird_freed then
        fn_say("Клетка уже открыта, птица на свободе.")
      else
        fn_say('Хозяин кладёт ладонь на дверцу: "Не трогайте соловья. Он поёт только по моим законам."')
      end
    else
      return false
    end
  end;
  before_Talk = function(s, w, wh)
    if w == _'господин' then
      if not boss_banished then
        fn_say('Он улыбается тонкой, нарисованной улыбкой. "Добро пожаловать. На улице — голод, тиф, тьма. А здесь — идеальный покой. Отдайте мне ваше зеркало, выпейте чаю с сахаром. Сюзанна вернётся к вам в фарфоре и шелках, совершенная и вечно молодая."')
      else
        fn_say("В кресле — лишь помятый цилиндр и опавшая визитка. Говорить не с кем.")
      end
    else
      return false
    end
  end;
  before_Show = function(s, w, wh)
    if w == _'осколок' and have(_'осколок') and not boss_banished then
      fn_say("Вы вскинули осколок перед его глазами. В амальгаме — плешивая крыса в золотой короне из шестерён. Тварь завизжала, дёрнула рычаг люка и провалилась в жерло мусоросброса.")
      boss_banished = true
    else
      return false
    end
  end;
  before_Give = function(s, w, wh)
    if w == _'осколок' and have(_'осколок') and not boss_banished then
      walk(_'dollend')
    else
      return false
    end
  end;
  obj = {
    obj {
      -"клетка|соловей|птица";
      nam = "клетка";
    }:attr 'scenery,scenery';

    obj {
      -"парусник|модель|корабль";
      nam = "парусник";
    }:attr 'scenery,scenery';

    obj {
      -"господин,председатель,хозяин";
      nam = "господин";
    }:attr 'animate';

    obj {
      -"печать";
      nam = "печать";
      before_Take = function(s, w, wh)
        if not boss_banished then
          fn_say('Господин накрывает печать ладонью: "Это печать Правления. Не торопите события."')
          return
        end
        fn_say("Тяжёлая печать Правления: шестерня, обвитая колосьями, и корона.")
        return false
      end;
    };

    obj {
      -"коридор|галерея";
      nam = "путь_кабинет_коридор";
      before_Walk = function(s, w, wh)
        move(me(), _'коридор')
      end;
      before_Enter = function(s, w, wh)
        move(me(), _'коридор')
      end;
    }:attr 'scenery,scenery';
  };
}

room {
